const client = "import { findConflicts, evaluateStock } from '/engine.js';\n\nconst FIELDS = {\n  revenue_yoy: { name: '营业收入同比', short: '营收同比', unit: '%', doc: 'https://fuyao.aicubes.cn/docs/api-reference/financials/' },\n  profit_yoy: { name: '归母净利润同比', short: '利润同比', unit: '%', doc: 'https://fuyao.aicubes.cn/docs/api-reference/financials/' },\n  pe_ttm: { name: '市盈率 TTM', short: 'PE TTM', unit: '倍', doc: 'https://fuyao.aicubes.cn/docs/api-reference/valuations/' },\n  pb_mrq: { name: '市净率 MRQ', short: 'PB MRQ', unit: '倍', doc: 'https://fuyao.aicubes.cn/docs/api-reference/valuations/' },\n  volatility_20d: { name: '20 日年化波动率', short: '20日波动', unit: '%', doc: 'https://fuyao.aicubes.cn/docs/api-reference/prices/' },\n};\nconst OPERATORS = { gt: '>', gte: '≥', lt: '<', lte: '≤', between: '区间' };\nconst DEFAULTS = [\n  { metric: 'revenue_yoy', op: 'gt', value: 0, label: '经营改善：营业收入同比为正' },\n  { metric: 'profit_yoy', op: 'gt', value: 0, label: '经营改善：归母净利润同比为正' },\n  { metric: 'pe_ttm', op: 'gt', value: 0, label: '估值口径：剔除非正市盈率' },\n  { metric: 'pe_ttm', op: 'lte', value: 30, label: '估值合理暂按 PE TTM ≤ 30 倍' },\n  { metric: 'volatility_20d', op: 'lte', value: 30, label: '稳定暂按近 20 日年化波动率 ≤ 30%' },\n];\nconst state = { user: null, market: null, conditions: structuredClone(DEFAULTS), assumptions: ['“估值合理”暂以 PE TTM 0–30 倍表达；“稳定”暂以 20 日年化波动率不超过 30% 表达。两项均为可修改的工作假设。'], unsupported: [], clarifications: [], intentBase: '', followUps: [], tab: 'pass', results: [], compare: new Set(), previousPass: null, loading: false, strategies: [] };\nconst $ = selector => document.querySelector(selector);\nconst esc = value => String(value ?? '').replace(/[&<>\"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[char]));\nconst num = (value, digits = 1) => typeof value === 'number' && Number.isFinite(value) ? new Intl.NumberFormat('zh-CN', { maximumFractionDigits: digits, minimumFractionDigits: digits }).format(value) : '—';\nconst asDateTime = value => value ? new Date(value).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—';\n\nfunction toast(message) {\n  const node = $('#toast'); node.textContent = message; node.classList.add('show');\n  clearTimeout(toast.timer); toast.timer = setTimeout(() => node.classList.remove('show'), 3300);\n}\n\nfunction showAuth() {\n  state.user = null;\n  state.market = null;\n  state.results = [];\n  state.conditions = structuredClone(DEFAULTS);\n  state.assumptions = [];\n  state.unsupported = [];\n  state.clarifications = [];\n  state.intentBase = '';\n  state.followUps = [];\n  state.compare.clear();\n  state.strategies = [];\n  state.previousPass = null;\n  $('#intent-input').value = '经营改善、估值合理、走势相对稳定';\n  $('#clarify-panel').hidden = true;\n  $('#auth-screen').hidden = false;\n  $('#app-shell').hidden = true;\n  $('#auth-password').value = '';\n  renderConditions();\n}\n\nfunction showApp(user) {\n  state.user = user;\n  $('#account-email').textContent = user.email;\n  $('#auth-screen').hidden = true;\n  $('#app-shell').hidden = false;\n  loadMarket();\n}\n\nfunction authMode(mode) {\n  document.querySelectorAll('.auth-tab').forEach(tab => tab.classList.toggle('active', tab.dataset.authMode === mode));\n  $('#auth-title').textContent = mode === 'register' ? '创建研究账号' : '欢迎使用明筛';\n  $('#auth-submit').innerHTML = mode === 'register' ? '注册并开始研究 <span>→</span>' : '登录并开始研究 <span>→</span>';\n  $('#auth-password').autocomplete = mode === 'register' ? 'new-password' : 'current-password';\n  $('#password-hint').hidden = mode !== 'register';\n  $('#auth-error').textContent = '';\n}\n\ndocument.querySelectorAll('.auth-tab').forEach(tab => tab.addEventListener('click', () => authMode(tab.dataset.authMode)));\n$('#auth-form').addEventListener('submit', async event => {\n  event.preventDefault();\n  const mode = document.querySelector('.auth-tab.active').dataset.authMode;\n  const button = $('#auth-submit'); button.disabled = true;\n  $('#auth-error').textContent = '';\n  try {\n    const response = await fetch(`/api/auth/${mode}`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ email: $('#auth-email').value, password: $('#auth-password').value }) });\n    const result = await response.json();\n    if (!response.ok) throw new Error(result.error || '账号操作失败');\n    showApp(result.user);\n  } catch (error) { $('#auth-error').textContent = error.message; }\n  finally { button.disabled = false; }\n});\n$('#logout-btn').addEventListener('click', async () => {\n  try { await fetch('/api/auth/logout', { method: 'POST' }); }\n  finally { showAuth(); }\n});\n$('#account-btn').addEventListener('click', () => { $('#account-error').textContent = ''; $('#delete-password').value = ''; $('#account-dialog').showModal(); });\n$('#close-account').addEventListener('click', () => $('#account-dialog').close());\n$('#account-dialog').addEventListener('click', event => { if (event.target === $('#account-dialog')) $('#account-dialog').close(); });\n$('#delete-account-form').addEventListener('submit', async event => {\n  event.preventDefault();\n  const button = event.target.querySelector('button[type=submit]'); button.disabled = true;\n  try {\n    const response = await fetch('/api/account', { method: 'DELETE', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ password: $('#delete-password').value }) });\n    const result = await response.json();\n    if (!response.ok || !result.deleted) throw new Error(result.error || '删除失败');\n    $('#account-dialog').close(); showAuth(); toast('账号和已保存策略已删除');\n  } catch (error) { $('#account-error').textContent = error.message; }\n  finally { button.disabled = false; }\n});\n\nfunction renderConditions() {\n  const list = $('#condition-list');\n  list.innerHTML = state.conditions.map((c, index) => `<div class=\"condition-card\" data-index=\"${index}\">\n    <span class=\"condition-number\">${String(index + 1).padStart(2, '0')}</span>\n    <label class=\"sr-only\" for=\"metric-${index}\">指标</label><select id=\"metric-${index}\" data-field=\"metric\">${Object.entries(FIELDS).map(([key, field]) => `<option value=\"${key}\" ${c.metric === key ? 'selected' : ''}>${field.name}</option>`).join('')}</select>\n    <label class=\"sr-only\" for=\"op-${index}\">比较方式</label><select id=\"op-${index}\" data-field=\"op\">${Object.entries(OPERATORS).map(([key, label]) => `<option value=\"${key}\" ${c.op === key ? 'selected' : ''}>${label}</option>`).join('')}</select>\n    <label class=\"sr-only\" for=\"value-${index}\">阈值</label><input id=\"value-${index}\" data-field=\"value\" type=\"number\" step=\"any\" value=\"${Number.isFinite(c.value) ? c.value : 0}\">\n    ${c.op === 'between' ? `<label class=\"sr-only\" for=\"max-${index}\">上限</label><input id=\"max-${index}\" data-field=\"max\" type=\"number\" step=\"any\" value=\"${Number.isFinite(c.max) ? c.max : 30}\">` : `<span class=\"condition-unit\">${FIELDS[c.metric]?.unit || ''}</span>`}\n    <button type=\"button\" class=\"remove-condition\" aria-label=\"删除第 ${index + 1} 条条件\" data-remove=\"${index}\">×</button>\n  </div>`).join('');\n  const assumptionBox = $('#assumptions');\n  assumptionBox.hidden = state.assumptions.length === 0 && state.clarifications.length === 0;\n  assumptionBox.innerHTML = [...state.assumptions.map(item => `工作假设：${esc(item)}`), ...state.clarifications.map(item => `待澄清：${esc(item)}`)].join('<br>');\n  const unsupportedBox = $('#unsupported');\n  unsupportedBox.hidden = state.unsupported.length === 0;\n  unsupportedBox.innerHTML = `<strong>当前数据无法执行：</strong>${state.unsupported.map(esc).join('；')}。这些要求未被静默纳入筛选。`;\n  const conflicts = findConflicts(state.conditions);\n  const conflictBox = $('#conflicts');\n  conflictBox.hidden = conflicts.length === 0;\n  conflictBox.innerHTML = `<strong>条件冲突：</strong>${conflicts.map(esc).join('；')}。请修改阈值后再看结果。`;\n  return conflicts;\n}\n\nfunction conditionText(c) {\n  const field = FIELDS[c.metric];\n  if (!field) return '未知条件';\n  return c.op === 'between' ? `${field.name} ${num(c.value)}–${num(c.max)} ${field.unit}` : `${field.name} ${OPERATORS[c.op]} ${num(c.value)} ${field.unit}`;\n}\n\nfunction execute() {\n  const conflicts = renderConditions();\n  if (!state.market || conflicts.length || !state.conditions.length) {\n    state.results = [];\n    renderStats(null);\n    renderResults();\n    return;\n  }\n  state.results = state.market.stocks.map(stock => evaluateStock(stock, state.conditions));\n  const currentPass = new Set(state.results.filter(item => item.status === 'pass').map(item => item.stock.code));\n  let delta = null;\n  if (state.previousPass) {\n    const addedCodes = [...currentPass].filter(code => !state.previousPass.has(code));\n    const removedCodes = [...state.previousPass].filter(code => !currentPass.has(code));\n    delta = { added: addedCodes.length, removed: removedCodes.length, addedCodes, removedCodes };\n  }\n  state.previousPass = currentPass;\n  renderStats(delta);\n  renderResults();\n}\n\nfunction renderStats(delta) {\n  const counts = { pass: 0, fail: 0, unknown: 0 };\n  state.results.forEach(item => { counts[item.status]++; });\n  for (const key of Object.keys(counts)) {\n    $(`#count-${key}`).textContent = state.market && state.conditions.length && !findConflicts(state.conditions).length ? counts[key] : '—';\n    $(`#tab-${key}`).textContent = counts[key];\n  }\n  $('#tab-compare').textContent = state.compare.size;\n  $('#count-delta').textContent = delta ? `+${delta.added} / −${delta.removed}` : '—';\n  $('#delta-caption').textContent = delta ? '新增入选 / 离开入选' : '相对上一次执行';\n  const changeDetail = $('#change-detail');\n  changeDetail.hidden = !delta || (!delta.added && !delta.removed);\n  if (delta) {\n    const name = code => state.market?.stocks.find(stock => stock.code === code)?.name || code;\n    changeDetail.innerHTML = `<strong>本次条件变化：</strong>${delta.added ? `<span>新入选 ${delta.added} 只：${delta.addedCodes.slice(0, 6).map(code => esc(name(code))).join('、')}${delta.added > 6 ? '等' : ''}</span>` : ''}${delta.removed ? `<span>离开入选 ${delta.removed} 只：${delta.removedCodes.slice(0, 6).map(code => esc(name(code))).join('、')}${delta.removed > 6 ? '等' : ''}</span>` : ''}`;\n  }\n  $('#result-subtitle').textContent = !state.market ? '数据载入后，会按当前条件确定性计算。' : findConflicts(state.conditions).length ? '当前条件存在冲突，需先修改。' : `以上证50当前 ${state.market.universeCount} 只成分股为范围，按 ${state.conditions.length} 条条件计算。`;\n}\n\nfunction statusSummary(item) {\n  if (item.status === 'pass') return '全部通过';\n  const target = item.checks.find(check => check.status === (item.status === 'fail' ? 'fail' : 'unknown'));\n  return `${item.status === 'fail' ? '未满足' : '缺失'}：${FIELDS[target?.condition?.metric]?.short || '条件'}`;\n}\n\nfunction stockRow(item) {\n  const stock = item.stock;\n  const cell = metric => {\n    const value = stock.metrics?.[metric]?.value;\n    return `<div class=\"metric-cell\"><small>${FIELDS[metric].short}</small><strong class=\"${value === null ? 'missing' : ''}\">${num(value)}${value === null ? '' : FIELDS[metric].unit}</strong></div>`;\n  };\n  return `<div class=\"stock-row\"><input class=\"row-select\" type=\"checkbox\" aria-label=\"选择 ${esc(stock.name)} 进行比较\" data-compare=\"${esc(stock.code)}\" ${state.compare.has(stock.code) ? 'checked' : ''}>\n    <button type=\"button\" class=\"stock-main\" data-stock=\"${esc(stock.code)}\"><strong>${esc(stock.name)}</strong><small>${esc(stock.code)} · ${stock.latestPrice === null ? '价格缺失' : `最新价 ${num(stock.latestPrice, 2)} 元`}</small></button>\n    ${cell('revenue_yoy')}${cell('profit_yoy')}${cell('pe_ttm')}${cell('volatility_20d')}\n    <div class=\"row-status\"><span class=\"pill ${item.status}\">${esc(statusSummary(item))}</span></div></div>`;\n}\n\nfunction renderCompare() {\n  const selected = state.results.filter(item => state.compare.has(item.stock.code)).slice(0, 3);\n  if (!selected.length) return `<div class=\"empty-state\"><strong>还没有比较对象</strong><p>在入选、排除或待核查列表勾选最多 3 只股票，即可并排比较关键数值和条件状态。</p></div>`;\n  const rows = [\n    ['筛选状态', item => item.status === 'pass' ? '入选' : item.status === 'fail' ? '排除' : '待核查'],\n    ['营业收入同比', item => `${num(item.stock.metrics.revenue_yoy.value)}%`],\n    ['归母净利润同比', item => `${num(item.stock.metrics.profit_yoy.value)}%`],\n    ['PE TTM', item => `${num(item.stock.metrics.pe_ttm.value)} 倍`],\n    ['PB MRQ', item => `${num(item.stock.metrics.pb_mrq.value)} 倍`],\n    ['20 日年化波动率', item => `${num(item.stock.metrics.volatility_20d.value)}%`],\n  ];\n  return `<table class=\"compare-table\"><thead><tr><th>指标</th>${selected.map(item => `<th><button type=\"button\" class=\"stock-main\" data-stock=\"${esc(item.stock.code)}\"><strong>${esc(item.stock.name)}</strong><small>${esc(item.stock.code)}</small></button></th>`).join('')}</tr></thead><tbody>${rows.map(([label, getValue]) => `<tr><td>${label}</td>${selected.map(item => `<td class=\"${getValue(item).includes('—') ? 'missing' : ''}\">${esc(getValue(item))}</td>`).join('')}</tr>`).join('')}</tbody></table>`;\n}\n\nfunction renderResults() {\n  const list = $('#result-list');\n  if (!state.market) { list.innerHTML = `<div class=\"empty-state\"><strong>正在等待真实数据</strong><p>页面会从扶摇接口获取上证50成分股、财务、估值与历史行情。</p></div>`; return; }\n  if (findConflicts(state.conditions).length || !state.conditions.length) { list.innerHTML = `<div class=\"empty-state\"><strong>尚不能执行筛选</strong><p>请解决冲突，或至少添加一条可执行条件。</p></div>`; return; }\n  if (state.tab === 'compare') { list.innerHTML = renderCompare(); return; }\n  const search = $('#stock-search').value.trim().toLowerCase();\n  const matched = state.results.filter(item => item.status === state.tab && (!search || `${item.stock.name} ${item.stock.code}`.toLowerCase().includes(search)));\n  list.innerHTML = matched.length ? matched.map(stockRow).join('') : `<div class=\"empty-state\"><strong>${search ? '没有匹配的股票' : '这一类目前为空'}</strong><p>${search ? '试试其他名称或股票代码。' : '修改阈值后，结果会重新计算并显示影响。'}</p></div>`;\n}\n\nfunction rawText(raw) {\n  if (!raw) return '无原始字段';\n  if ('currentField' in raw) return `${raw.currentField}: ${num(raw.current, 2)} ${esc(raw.currency || 'CNY')}；同期 ${raw.priorField}: ${num(raw.prior, 2)} ${esc(raw.currency || 'CNY')}`;\n  if ('field' in raw) return `${raw.field}: ${num(raw.value, 3)}`;\n  return `close_price: ${raw.pricePoints || 0} 个交易日数据；${raw.adjust || ''} 复权`;\n}\n\nfunction openStock(code) {\n  const item = state.results.find(row => row.stock.code === code);\n  if (!item) return;\n  const stock = item.stock;\n  const pill = item.status === 'pass' ? '入选' : item.status === 'fail' ? '排除' : '待核查';\n  const evidence = item.checks.map(({ condition, status }) => {\n    const value = stock.metrics[condition.metric];\n    return `<tr><td>${esc(conditionText(condition))}</td><td>${value?.value === null ? '<span class=\"missing\">数据缺失</span>' : `${num(value?.value, 2)} ${esc(value?.unit)}`}</td><td><span class=\"pill ${status}\">${status === 'pass' ? '通过' : status === 'fail' ? '未通过' : '缺失'}</span></td><td>${esc(value?.source?.reportEnd || value?.source?.asOf || '—')}</td></tr>`;\n  }).join('');\n  const sources = [...new Set(item.checks.map(({ condition }) => condition.metric))].map(key => {\n    const value = stock.metrics[key]; const source = value?.source || {};\n    return `<details class=\"source-card\"><summary>${esc(FIELDS[key].name)} · 查看原始依据</summary><p>来源：${esc(source.provider || '—')} · <a href=\"${FIELDS[key].doc}\" target=\"_blank\" rel=\"noopener noreferrer\">字段文档 ↗</a><br>接口：<code>${esc(source.endpoint || '—')}</code><br>报告期：${esc(source.reportEnd || '—')} · 披露日：${esc(source.published || '—')} · 比较期：${esc(source.priorReportEnd || '—')} · 数据日期：${esc(source.asOf || '—')}<br>原始字段：${rawText(value.raw)}<br>计算口径：${esc(source.method || '—')}<br>请求追踪 ID：${esc(source.requestId || '未提供')}</p></details>`;\n  }).join('');\n  $('#dialog-body').innerHTML = `<div class=\"section-index\">EVIDENCE / ${esc(stock.code)}</div><div class=\"dialog-head\"><div><h2 id=\"dialog-title\">${esc(stock.name)}</h2><p>${esc(stock.code)} · 最新价 ${num(stock.latestPrice, 2)} 元 · 行情日期 ${esc(stock.priceAsOf || '—')}</p></div><span class=\"pill ${item.status}\">${pill}</span></div><div class=\"dialog-summary\">${item.status === 'pass' ? '当前所有条件均有数据且通过。' : item.status === 'fail' ? `至少一项未达到条件：${esc(item.checks.filter(row => row.status === 'fail').map(row => conditionText(row.condition)).join('；'))}` : '没有明确未通过的条件，但至少一项必要数据缺失。'}${stock.missing?.length ? `<br>接口情况：${stock.missing.map(esc).join('；')}` : ''}</div><table class=\"evidence-table\"><thead><tr><th>当前条件</th><th>实际数据</th><th>结论</th><th>时点</th></tr></thead><tbody>${evidence}</tbody></table><div style=\"margin-top:22px\" class=\"section-index\">SOURCE TRACE / 原始依据</div>${sources}`;\n  $('#stock-dialog').showModal();\n}\n\nasync function loadMarket(refresh = false) {\n  if (state.loading) return;\n  state.loading = true;\n  $('#refresh-data').disabled = true;\n  $('#data-status').className = 'data-status'; $('#data-status').textContent = refresh ? '正在重新获取真实数据…' : '正在连接扶摇金融数据…';\n  $('#top-data-state').textContent = '正在取数';\n  try {\n    const response = await fetch(`/api/market${refresh ? '?refresh=1' : ''}`);\n    const data = await response.json();\n    if (!response.ok) throw new Error(data.error || `接口返回 ${response.status}`);\n    if (!Array.isArray(data.stocks) || data.stocks.length !== data.universeCount) throw new Error('返回的成分股数据不完整');\n    state.market = data;\n    state.previousPass = null;\n    $('#universe-count').textContent = data.universeCount;\n    $('#universe-asof').textContent = data.universeAsOf || '未提供';\n    $('#fetched-at').textContent = asDateTime(data.fetchedAt);\n    $('#data-status').className = 'data-status ok'; $('#data-status').textContent = `${data.stocks.length} 只成分股已载入 · ${data.cache === 'memory' || data.cache === 'database' ? '15 分钟共享缓存' : '本次实时获取'}`;\n    $('#top-data-state').textContent = '真实数据已连接';\n    $('#tool-footprint').innerHTML = `<strong>工具调用足迹</strong>${(data.toolFootprint || []).map(item => `<div><span>${({ snapshot: '行情快照', valuation: '估值快照', income: '批量利润表', history: '批量日线' })[item.type] || esc(item.type)}</span><span>${item.succeeded}/${item.requests} 成功</span></div>`).join('')}`;\n    const issues = $('#api-issues'); issues.hidden = !data.issues.length;\n    issues.innerHTML = data.issues.length ? `<strong>部分数据获取异常：</strong><br>${data.issues.map(item => `${esc(item.type)} 影响 ${item.affected} 只`).join('<br>')}` : '';\n    execute();\n  } catch (error) {\n    if (/请先注册或登录/.test(error.message)) return showAuth();\n    $('#data-status').className = 'data-status error'; $('#data-status').textContent = error.message || '取数失败';\n    $('#top-data-state').textContent = '数据连接异常';\n    toast('数据连接失败，请检查接口状态后重试');\n    if (!state.market) renderResults();\n  } finally { state.loading = false; $('#refresh-data').disabled = false; }\n}\n\nfunction renderClarify() {\n  $('#clarify-panel').hidden = false;\n  $('#clarify-questions').innerHTML = state.clarifications.length ? `<strong>AI 待确认：</strong>${state.clarifications.map(esc).join('；')}` : '还想补充吗？你可以说明行业偏好、指标阈值，或修正刚才的表达。';\n  $('#clarify-history').textContent = state.followUps.length ? `已补充：${state.followUps.join(' → ')}` : '';\n}\n\nasync function interpret(followUp = false) {\n  const text = followUp ? state.intentBase : $('#intent-input').value.trim();\n  if (!text) { toast('请先输入选股意图'); return; }\n  const reply = followUp ? $('#clarify-input').value.trim() : '';\n  if (followUp && !reply) return toast('请先输入补充说明');\n  if (followUp && state.followUps.length >= 3) return toast('最多补充三轮，请直接修改原始意图后重新解析');\n  const followUps = followUp ? [...state.followUps, reply] : [];\n  const button = followUp ? $('#clarify-submit') : $('#interpret-btn'); button.disabled = true; $('#interpret-status').textContent = 'DeepSeek 正在理解意图并生成可检查条件…';\n  try {\n    const response = await fetch('/api/interpret', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ text, followUps }) });\n    const result = await response.json();\n    if (!response.ok) throw new Error(result.error || '解析失败');\n    state.intentBase = text;\n    state.followUps = followUps;\n    state.unsupported = result.unsupported || [];\n    state.clarifications = result.clarifications || [];\n    state.assumptions = result.assumptions || [];\n    renderClarify();\n    $('#clarify-input').value = '';\n    if (!result.conditions.length) {\n      state.conditions = [];\n      execute();\n      $('#interpret-status').textContent = '没有识别出可由当前 5 个指标执行的条件。请修改描述或手动添加条件。';\n      return;\n    }\n    state.conditions = result.conditions;\n    $('#interpret-status').textContent = `DeepSeek 已理解 ${followUps.length ? '补充后的' : ''}意图，生成 ${result.conditions.length} 条条件草案。请核对阈值。`;\n    execute();\n    if (!followUp) $('#conditions').scrollIntoView({ behavior: 'smooth', block: 'start' });\n  } catch (error) { if (/请先注册或登录/.test(error.message)) return showAuth(); $('#interpret-status').textContent = error.message; toast('AI 暂不可用，可手动修改当前条件'); }\n  finally { button.disabled = false; }\n}\n\n$('#interpret-btn').addEventListener('click', () => interpret(false));\n$('#clarify-submit').addEventListener('click', () => interpret(true));\n$('#clarify-input').addEventListener('keydown', event => { if (event.key === 'Enter') { event.preventDefault(); interpret(true); } });\ndocument.querySelectorAll('.example').forEach(button => button.addEventListener('click', () => { $('#intent-input').value = button.dataset.prompt; $('#intent-input').focus(); }));\n$('#condition-list').addEventListener('change', event => {\n  const card = event.target.closest('.condition-card'); if (!card) return;\n  const index = Number(card.dataset.index); const field = event.target.dataset.field;\n  if (!field) return;\n  state.conditions[index][field] = field === 'value' || field === 'max' ? Number(event.target.value) : event.target.value;\n  if (field === 'op' && event.target.value === 'between' && !Number.isFinite(state.conditions[index].max)) state.conditions[index].max = 30;\n  state.conditions[index].label = '用户已修改';\n  execute();\n});\n$('#condition-list').addEventListener('click', event => {\n  const remove = event.target.closest('[data-remove]'); if (!remove) return;\n  state.conditions.splice(Number(remove.dataset.remove), 1); execute();\n});\n$('#add-condition').addEventListener('click', () => { if (state.conditions.length >= 8) return toast('最多支持 8 条条件'); state.conditions.push({ metric: 'revenue_yoy', op: 'gte', value: 0, label: '用户添加' }); execute(); });\n$('#reset-conditions').addEventListener('click', () => { state.conditions = structuredClone(DEFAULTS); state.assumptions = ['示例阈值均可修改；PE TTM 范围与年化波动率不是统一投资标准。']; state.unsupported = []; state.clarifications = []; execute(); toast('已恢复示例条件'); });\n$('#refresh-data').addEventListener('click', () => loadMarket(true));\ndocument.querySelectorAll('.tab').forEach(button => button.addEventListener('click', () => { state.tab = button.dataset.tab; document.querySelectorAll('.tab').forEach(tab => { tab.classList.toggle('active', tab === button); tab.setAttribute('aria-selected', String(tab === button)); }); renderResults(); }));\n$('#stock-search').addEventListener('input', renderResults);\n$('#result-list').addEventListener('click', event => { const button = event.target.closest('[data-stock]'); if (button) openStock(button.dataset.stock); });\n$('#result-list').addEventListener('change', event => {\n  const box = event.target.closest('[data-compare]'); if (!box) return;\n  if (box.checked && state.compare.size >= 3) { box.checked = false; toast('最多比较 3 只股票'); return; }\n  if (box.checked) state.compare.add(box.dataset.compare); else state.compare.delete(box.dataset.compare);\n  $('#tab-compare').textContent = state.compare.size;\n  if (state.tab === 'compare') renderResults();\n});\n$('#close-dialog').addEventListener('click', () => $('#stock-dialog').close());\n$('#stock-dialog').addEventListener('click', event => { if (event.target === $('#stock-dialog')) $('#stock-dialog').close(); });\n$('#save-strategy').addEventListener('click', async () => {\n  if (!state.conditions.length || findConflicts(state.conditions).length) return toast('请先保留至少一条无冲突条件');\n  try {\n    const text = $('#intent-input').value.trim();\n    const response = await fetch('/api/strategies', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title: text.slice(0, 60) || '手动筛选策略', text, conditions: state.conditions, assumptions: state.assumptions }) });\n    const result = await response.json();\n    if (!response.ok) throw new Error(result.error || '保存失败');\n    toast('策略已保存到账号，可在其他设备登录后读取');\n  } catch (error) { toast(error.message); }\n});\n\nasync function listStrategies() {\n  const response = await fetch('/api/strategies');\n  const data = await response.json();\n  if (!response.ok) throw new Error(data.error || '读取失败');\n  state.strategies = data.strategies;\n  $('#strategy-list').innerHTML = state.strategies.length ? state.strategies.map(item => `<div class=\"strategy-item\"><div><strong>${esc(item.title)}</strong><small>${item.conditions.length} 条条件 · ${asDateTime(item.updatedAt)}</small></div><div class=\"strategy-item-actions\"><button type=\"button\" data-load=\"${esc(item.id)}\">载入</button><button type=\"button\" data-delete=\"${esc(item.id)}\">删除</button></div></div>`).join('') : '<div class=\"empty-state\"><strong>还没有已保存策略</strong><p>调整并执行条件后，点击“保存本次条件”。</p></div>';\n}\n$('#load-strategy').addEventListener('click', async () => {\n  try { await listStrategies(); $('#strategies-dialog').showModal(); }\n  catch (error) { toast(error.message); }\n});\n$('#close-strategies').addEventListener('click', () => $('#strategies-dialog').close());\n$('#strategies-dialog').addEventListener('click', event => { if (event.target === $('#strategies-dialog')) $('#strategies-dialog').close(); });\n$('#strategy-list').addEventListener('click', async event => {\n  const loadButton = event.target.closest('[data-load]');\n  if (loadButton) {\n    const saved = state.strategies.find(item => item.id === loadButton.dataset.load);\n    if (!saved) return;\n    state.conditions = saved.conditions.filter(c => FIELDS[c.metric] && OPERATORS[c.op]).slice(0, 8);\n    state.assumptions = saved.assumptions || [];\n    state.unsupported = []; state.clarifications = [];\n    $('#intent-input').value = saved.text || '';\n    $('#strategies-dialog').close(); execute();\n    toast('已按当前市场数据重新执行保存的条件');\n    return;\n  }\n  const deleteButton = event.target.closest('[data-delete]');\n  if (deleteButton) {\n    try {\n      const response = await fetch(`/api/strategies/${deleteButton.dataset.delete}`, { method: 'DELETE' });\n      const result = await response.json();\n      if (!response.ok || !result.deleted) throw new Error(result.error || '删除失败');\n      await listStrategies(); toast('已删除策略');\n    } catch (error) { toast(error.message); }\n  }\n});\n\nrenderConditions(); renderResults();\nfetch('/api/session').then(async response => { const result = await response.json(); if (!response.ok) throw new Error(result.error); if (result.user) showApp(result.user); else showAuth(); }).catch(error => { showAuth(); $('#auth-error').textContent = error.message || '账号服务暂不可用'; });\n";
const engine = "const METRIC_NAMES = {\n  revenue_yoy: '营业收入同比',\n  profit_yoy: '归母净利润同比',\n  pe_ttm: '市盈率 TTM',\n  pb_mrq: '市净率 MRQ',\n  volatility_20d: '20 日年化波动率',\n};\n\nexport function findConflicts(conditions) {\n  const errors = [];\n  for (const [metric, name] of Object.entries(METRIC_NAMES)) {\n    let low = -Infinity, high = Infinity, lowInclusive = true, highInclusive = true;\n    for (const c of conditions.filter(item => item.metric === metric)) {\n      if (!Number.isFinite(c.value) || (c.op === 'between' && !Number.isFinite(c.max))) { errors.push(`${name} 的阈值不是有效数字`); continue; }\n      if (c.op === 'between' && c.value > c.max) errors.push(`${name} 的区间下限高于上限`);\n      const lowers = c.op === 'gt' || c.op === 'gte' || c.op === 'between';\n      const uppers = c.op === 'lt' || c.op === 'lte' || c.op === 'between';\n      if (lowers && (c.value > low || (c.value === low && c.op === 'gt'))) { low = c.value; lowInclusive = c.op !== 'gt'; }\n      const top = c.op === 'between' ? c.max : c.value;\n      if (uppers && (top < high || (top === high && c.op === 'lt'))) { high = top; highInclusive = c.op !== 'lt'; }\n    }\n    if (low > high || (low === high && (!lowInclusive || !highInclusive))) errors.push(`${name} 同时要求高于 ${low} 且低于 ${high}`);\n  }\n  return [...new Set(errors)];\n}\n\nexport function check(stock, condition) {\n  const value = stock.metrics?.[condition.metric]?.value;\n  if (!Number.isFinite(value)) return 'unknown';\n  const target = condition.value;\n  if (condition.op === 'gt') return value > target ? 'pass' : 'fail';\n  if (condition.op === 'gte') return value >= target ? 'pass' : 'fail';\n  if (condition.op === 'lt') return value < target ? 'pass' : 'fail';\n  if (condition.op === 'lte') return value <= target ? 'pass' : 'fail';\n  if (condition.op === 'between') return value >= target && value <= condition.max ? 'pass' : 'fail';\n  return 'unknown';\n}\n\nexport function evaluateStock(stock, conditions) {\n  const checks = conditions.map(condition => ({ condition, status: check(stock, condition) }));\n  const status = checks.some(item => item.status === 'fail') ? 'fail' : checks.some(item => item.status === 'unknown') ? 'unknown' : 'pass';\n  return { stock, checks, status };\n}\n";

const BASE = 'https://fuyao.aicubes.cn';
const UNIVERSE = '000016.SH';
const METRICS = new Set(['revenue_yoy', 'profit_yoy', 'pe_ttm', 'pb_mrq', 'volatility_20d']);
const SESSION_DAYS = 7;
const encoder = new TextEncoder();

function accountJson(body, status = 200, headers = {}) {
  return new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', ...headers } });
}

function db(env) {
  if (!env.DB?.prepare) throw new Error('账号数据库尚未连接');
  return env.DB;
}

function base64(bytes) {
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
}

function unbase64(value) {
  return Uint8Array.from(atob(value), char => char.charCodeAt(0));
}

async function sha256(text) {
  return [...new Uint8Array(await crypto.subtle.digest('SHA-256', encoder.encode(text)))].map(byte => byte.toString(16).padStart(2, '0')).join('');
}

async function passwordHash(password, salt, pepper) {
  if (!pepper) throw new Error('账号加密密钥尚未配置');
  const hmacKey = await crypto.subtle.importKey('raw', encoder.encode(pepper), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const mixed = await crypto.subtle.sign('HMAC', hmacKey, encoder.encode(password));
  const key = await crypto.subtle.importKey('raw', mixed, 'PBKDF2', false, ['deriveBits']);
  return base64(new Uint8Array(await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: unbase64(salt), iterations: 100000 }, key, 256)));
}

function equalBytes(a, b) {
  const left = unbase64(a); const right = unbase64(b);
  if (left.length !== right.length) return false;
  let difference = 0;
  for (let i = 0; i < left.length; i++) difference |= left[i] ^ right[i];
  return difference === 0;
}

async function rateLimit(database, key, max, windowMs) {
  const period = Math.floor(Date.now() / windowMs);
  const scope = `${key}:${period}`;
  await database.prepare('INSERT INTO request_rates (key, period, count) VALUES (?, ?, 1) ON CONFLICT(key) DO UPDATE SET count = count + 1').bind(scope, period).run();
  const row = await database.prepare('SELECT count FROM request_rates WHERE key = ?').bind(scope).first();
  return row.count <= max;
}

function sameOrigin(request) {
  const origin = request.headers.get('origin');
  if (origin && origin !== new URL(request.url).origin) return false;
  return request.headers.get('sec-fetch-site') !== 'cross-site';
}

function sessionCookie(token, request) {
  const secure = new URL(request.url).protocol === 'https:' ? '; Secure' : '';
  return `ms_session=${token}; HttpOnly${secure}; SameSite=Lax; Path=/; Max-Age=${SESSION_DAYS * 86400}`;
}

function clearCookie(request) {
  return sessionCookie('', request).replace(/Max-Age=\d+/, 'Max-Age=0');
}

async function createSession(database, userId, request) {
  const token = base64(crypto.getRandomValues(new Uint8Array(32))).replaceAll('+', '-').replaceAll('/', '_').replaceAll('=', '');
  const now = Date.now();
  await database.prepare('INSERT INTO sessions (token_hash, user_id, created_at, expires_at) VALUES (?, ?, ?, ?)').bind(await sha256(token), userId, now, now + SESSION_DAYS * 86400000).run();
  return sessionCookie(token, request);
}

async function currentUser(request, env) {
  const token = request.headers.get('cookie')?.match(/(?:^|;\s*)ms_session=([^;]+)/)?.[1];
  if (!token) return null;
  const row = await db(env).prepare('SELECT u.id, u.email FROM sessions s JOIN users u ON u.id = s.user_id WHERE s.token_hash = ? AND s.expires_at > ?').bind(await sha256(token), Date.now()).first();
  return row ? { id: row.id, email: row.email } : null;
}

function validConditions(value) {
  return Array.isArray(value) && value.length > 0 && value.length <= 8 && value.every(item => item && METRICS.has(item.metric) && ['gt', 'gte', 'lt', 'lte', 'between'].includes(item.op) && Number.isFinite(item.value) && (item.op !== 'between' || Number.isFinite(item.max)));
}

async function accountRoute(request, env, url) {
  const database = db(env);
  const path = url.pathname;
  const method = request.method;
  if (method !== 'GET' && !sameOrigin(request)) return accountJson({ error: '跨站请求被拒绝' }, 403);
  if (path === '/api/session' && method === 'GET') return accountJson({ user: await currentUser(request, env) });

  if ((path === '/api/auth/register' || path === '/api/auth/login') && method === 'POST') {
    const body = await request.json().catch(() => ({}));
    const email = String(body.email || '').trim().toLowerCase();
    const password = String(body.password || '');
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || email.length > 254) return accountJson({ error: '请输入有效邮箱地址' }, 400);
    if (password.length > 128) return accountJson({ error: '密码长度不能超过 128 个字符' }, 400);
    const ip = request.headers.get('cf-connecting-ip') || 'local';
    const identity = await sha256(`${ip}:${email}`);
    const limit = path.endsWith('register') ? 5 : 10;
    if (!await rateLimit(database, `${path}:${identity}`, limit, path.endsWith('register') ? 3600000 : 900000)) return accountJson({ error: '尝试次数过多，请稍后再试' }, 429);
    if (path.endsWith('register')) {
      if (password.length < 12 || password.length > 128) return accountJson({ error: '密码长度须为 12–128 个字符' }, 400);
      let stage = 'lookup';
      try {
        const existing = await database.prepare('SELECT id FROM users WHERE email = ?').bind(email).first();
        if (existing) return accountJson({ error: '此邮箱已注册，请登录' }, 409);
        stage = 'random';
        const id = crypto.randomUUID();
        const salt = base64(crypto.getRandomValues(new Uint8Array(16)));
        stage = 'hash';
        const hash = await passwordHash(password, salt, env.AUTH_PEPPER);
        stage = 'insert';
        try { await database.prepare('INSERT INTO users (id, email, password_salt, password_hash, created_at) VALUES (?, ?, ?, ?, ?)').bind(id, email, salt, hash, Date.now()).run(); }
        catch { return accountJson({ error: '邮箱已注册或注册失败' }, 409); }
        stage = 'session';
        return accountJson({ user: { id, email } }, 201, { 'set-cookie': await createSession(database, id, request) });
      } catch (error) {
        console.error('MINGSHAI_REGISTER_ERROR', stage, error?.name || 'Error', error?.message || 'unknown');
        return accountJson({ error: '注册服务暂不可用', code: `register_${stage}` }, 503);
      }
    }
    const user = await database.prepare('SELECT id, email, password_salt, password_hash FROM users WHERE email = ?').bind(email).first();
    const candidate = await passwordHash(password, user?.password_salt || base64(new Uint8Array(16)), env.AUTH_PEPPER);
    if (!user || !equalBytes(candidate, user.password_hash)) return accountJson({ error: '邮箱或密码不正确' }, 401);
    return accountJson({ user: { id: user.id, email: user.email } }, 200, { 'set-cookie': await createSession(database, user.id, request) });
  }

  const user = await currentUser(request, env);
  if (!user) return accountJson({ error: '请先登录账号' }, 401);
  if (path === '/api/auth/logout' && method === 'POST') {
    const token = request.headers.get('cookie')?.match(/(?:^|;\s*)ms_session=([^;]+)/)?.[1];
    if (token) await database.prepare('DELETE FROM sessions WHERE token_hash = ?').bind(await sha256(token)).run();
    return accountJson({ ok: true }, 200, { 'set-cookie': clearCookie(request) });
  }
  if (path === '/api/account' && method === 'DELETE') {
    const body = await request.json().catch(() => ({}));
    const password = String(body.password || '');
    if (!password || password.length > 128) return accountJson({ error: '请输入当前密码' }, 400);
    const row = await database.prepare('SELECT password_salt, password_hash FROM users WHERE id = ?').bind(user.id).first();
    if (!row || !equalBytes(await passwordHash(password, row.password_salt, env.AUTH_PEPPER), row.password_hash)) return accountJson({ error: '密码不正确' }, 403);
    await database.prepare('DELETE FROM users WHERE id = ?').bind(user.id).run();
    return accountJson({ deleted: true }, 200, { 'set-cookie': clearCookie(request) });
  }

  if (path === '/api/strategies' && method === 'GET') {
    const result = await database.prepare('SELECT id, title, prompt, conditions_json, assumptions_json, created_at, updated_at FROM strategies WHERE user_id = ? ORDER BY updated_at DESC LIMIT 50').bind(user.id).all();
    return accountJson({ strategies: result.results.map(row => ({ id: row.id, title: row.title, text: row.prompt, conditions: JSON.parse(row.conditions_json), assumptions: JSON.parse(row.assumptions_json), createdAt: row.created_at, updatedAt: row.updated_at })) });
  }
  if (path === '/api/strategies' && method === 'POST') {
    const body = await request.json().catch(() => ({}));
    if (!validConditions(body.conditions)) return accountJson({ error: '策略条件无效，至少需要一条可执行条件' }, 400);
    const title = String(body.title || body.text || '未命名策略').trim().slice(0, 80);
    const prompt = String(body.text || '').slice(0, 500);
    const assumptions = Array.isArray(body.assumptions) ? body.assumptions.slice(0, 8).map(x => String(x).slice(0, 160)) : [];
    const id = crypto.randomUUID(); const now = Date.now();
    await database.prepare('INSERT INTO strategies (id, user_id, title, prompt, conditions_json, assumptions_json, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)').bind(id, user.id, title, prompt, JSON.stringify(body.conditions), JSON.stringify(assumptions), now, now).run();
    return accountJson({ id, title, savedAt: now }, 201);
  }
  const match = path.match(/^\/api\/strategies\/([0-9a-f-]{36})$/);
  if (match && method === 'DELETE') {
    const result = await database.prepare('DELETE FROM strategies WHERE id = ? AND user_id = ?').bind(match[1], user.id).run();
    return accountJson({ deleted: result.meta?.changes || 0 });
  }
  return accountJson({ error: '未知账号接口' }, 404);
}

let marketCache = null;
let marketPromise = null;

function json(body, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'cache-control': 'no-store',
    },
  });
}

function chunks(items, size) {
  const out = [];
  for (let index = 0; index < items.length; index += size) out.push(items.slice(index, index + size));
  return out;
}

async function fuyao(env, path, params, timeoutMs = 18000) {
  if (!env.FUYAO_API_KEY) throw new Error('金融数据服务尚未配置');
  const url = new URL(path, BASE);
  for (const [key, value] of Object.entries(params)) url.searchParams.set(key, String(value));
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(url, {
      headers: { 'X-api-key': env.FUYAO_API_KEY, accept: 'application/json' },
      signal: controller.signal,
    });
    const body = await response.json();
    if (!response.ok || body.code !== 0 || !body.data) {
      throw new Error(`${path} 返回 ${body.code ?? response.status}: ${body.message || '未知错误'}`);
    }
    return { data: body.data, requestId: body.request_id || null };
  } finally {
    clearTimeout(timer);
  }
}

async function limitedMap(items, limit, task) {
  const results = new Array(items.length);
  let next = 0;
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (next < items.length) {
      const index = next++;
      try { results[index] = { ok: true, value: await task(items[index]) }; }
      catch (error) { results[index] = { ok: false, error: String(error?.message || error) }; }
    }
  }));
  return results;
}

function validNumber(value) {
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

function date(ms) {
  return typeof ms === 'number' && Number.isFinite(ms) ? new Date(ms).toISOString().slice(0, 10) : null;
}

function metric(value, unit, source, extras = {}) {
  return { value: validNumber(value), unit, source, ...extras };
}

function growth(current, previous) {
  if (!Number.isFinite(current) || !Number.isFinite(previous) || previous <= 0) return null;
  return ((current / previous) - 1) * 100;
}

function volatility(bars) {
  const closes = bars.map(row => validNumber(row.close_price)).filter(value => value !== null);
  if (closes.length < 21) return null;
  const last = closes.slice(-21);
  const returns = [];
  for (let index = 1; index < last.length; index++) {
    if (last[index - 1] <= 0) return null;
    returns.push(Math.log(last[index] / last[index - 1]));
  }
  const average = returns.reduce((sum, value) => sum + value, 0) / returns.length;
  const variance = returns.reduce((sum, value) => sum + (value - average) ** 2, 0) / (returns.length - 1);
  return Math.sqrt(variance * 252) * 100;
}

function normalize(universe, snapshotResult, valuationResult, incomeGroups, priceGroups, issues) {
  const snapshots = new Map((snapshotResult?.data?.item || []).map(row => [row.thscode, row]));
  const valuations = new Map((valuationResult?.data?.item || []).map(row => [row.thscode, row]));
  const incomes = new Map(incomeGroups.map(group => [group.thscode, group]));
  const histories = new Map(priceGroups.map(group => [group.thscode, group]));
  return universe.map(stock => {
    const code = stock.thscode;
    const incomeGroup = incomes.get(code);
    const rows = (incomeGroup?.item || []).filter(row => row?.period_end_ms && row?.report_date_ms && row.report_date_ms <= Date.now());
    const latest = rows[0] || null;
    const comparable = latest ? rows.find(row => row.fiscal_year === latest.fiscal_year - 1 && row.fiscal_period === latest.fiscal_period) : null;
    const valuation = valuations.get(code);
    const history = histories.get(code);
    const bars = (history?.item || []).filter(row => row?.date_ms && row.date_ms <= Date.now());
    const snap = snapshots.get(code);
    const incomeSource = {
      provider: '扶摇金融数据', endpoint: '/api/a-share/financials/income-statements-batch',
      requestId: incomeGroup?._requestId || null,
      reportEnd: date(latest?.period_end_ms), published: date(latest?.report_date_ms),
      priorReportEnd: date(comparable?.period_end_ms), priorPublished: date(comparable?.report_date_ms),
      method: '同一财报期间的本年累计值 ÷ 上年同期累计值 − 1；上年值≤0时记为缺失',
    };
    const valuationSource = {
      provider: '扶摇金融数据', endpoint: '/api/a-share/valuations/snapshot',
      requestId: valuationResult?.requestId || null,
      asOf: date(valuationResult?.data?.timestamp), method: '接口原始估值；TTM 为近十二个月，MRQ 为最新报告期',
    };
    const historySource = {
      provider: '扶摇金融数据', endpoint: '/api/a-share/prices/historical-batch',
      requestId: history?._requestId || null, asOf: date(bars.at(-1)?.date_ms),
      method: '前复权日收盘价最近21个点的20个对数收益率，样本标准差 × √252，单位%',
    };
    return {
      code, name: stock.name || snap?.name || valuation?.name || code,
      latestPrice: validNumber(snap?.last_price),
      priceAsOf: date(snapshotResult?.data?.timestamp),
      metrics: {
        revenue_yoy: metric(growth(latest?.operating_income, comparable?.operating_income), '%', incomeSource, {
          raw: { currentField: 'operating_income', current: validNumber(latest?.operating_income), priorField: 'operating_income', prior: validNumber(comparable?.operating_income), currency: latest?.currency || 'CNY' },
        }),
        profit_yoy: metric(growth(latest?.parent_holder_net_profit, comparable?.parent_holder_net_profit), '%', incomeSource, {
          raw: { currentField: 'parent_holder_net_profit', current: validNumber(latest?.parent_holder_net_profit), priorField: 'parent_holder_net_profit', prior: validNumber(comparable?.parent_holder_net_profit), currency: latest?.currency || 'CNY' },
        }),
        pe_ttm: metric(valuation?.pe_ttm, '倍', valuationSource, { raw: { field: 'pe_ttm', value: validNumber(valuation?.pe_ttm) } }),
        pb_mrq: metric(valuation?.pb_mrq, '倍', valuationSource, { raw: { field: 'pb_mrq', value: validNumber(valuation?.pb_mrq) } }),
        volatility_20d: metric(volatility(bars), '%', historySource, { raw: { closeField: 'close_price', pricePoints: bars.length, adjust: 'forward', interval: '1d' } }),
      },
      missing: issues.filter(issue => issue.codes.includes(code)).map(issue => issue.message),
    };
  });
}

async function loadMarket(env) {
  const universeResult = await fuyao(env, '/api/a-share-index/constituents/ths-stock-list', { thscode: UNIVERSE });
  const universe = universeResult.data.item || [];
  if (universe.length < 40 || universe.length > 60) throw new Error(`上证50成分数量异常：${universe.length}`);
  const codes = universe.map(item => item.thscode);
  const batches = chunks(codes, 10);
  const priceStart = Date.now() - 125 * 86400000;
  const priceEnd = Date.now();
  const jobs = [
    { type: 'snapshot', codes, path: '/api/a-share/prices/snapshot', params: { thscodes: codes.join(',') } },
    { type: 'valuation', codes, path: '/api/a-share/valuations/snapshot', params: { thscodes: codes.join(',') } },
    ...batches.map(batch => ({ type: 'income', codes: batch, path: '/api/a-share/financials/income-statements-batch', params: { thscodes: batch.join(','), period: 'quarterly', limit: 12 } })),
    ...batches.map(batch => ({ type: 'history', codes: batch, path: '/api/a-share/prices/historical-batch', params: { thscodes: batch.join(','), interval: '1d', adjust: 'forward', start: priceStart, end: priceEnd } })),
  ];
  const done = await limitedMap(jobs, 4, job => fuyao(env, job.path, job.params, 25000));
  const issues = [];
  let snapshotResult = null;
  let valuationResult = null;
  const incomeGroups = [];
  const priceGroups = [];
  done.forEach((result, index) => {
    const job = jobs[index];
    if (!result.ok) {
      issues.push({ type: job.type, codes: job.codes, message: `${job.type}：${result.error}` });
      return;
    }
    const value = result.value;
    if (job.type === 'snapshot') snapshotResult = value;
    if (job.type === 'valuation') valuationResult = value;
    if (job.type === 'income') incomeGroups.push(...(value.data.item || []).map(group => ({ ...group, _requestId: value.requestId })));
    if (job.type === 'history') priceGroups.push(...(value.data.item || []).map(group => ({ ...group, _requestId: value.requestId })));
  });
  return {
    universe: '上证50', universeCode: UNIVERSE, universeCount: universe.length,
    universeAsOf: date(universeResult.data.timestamp), fetchedAt: new Date().toISOString(),
    stocks: normalize(universe, snapshotResult, valuationResult, incomeGroups, priceGroups, issues),
    issues: issues.map(({ type, codes, message }) => ({ type, affected: codes.length, message })),
    toolFootprint: ['snapshot', 'valuation', 'income', 'history'].map(type => ({
      type, requests: jobs.filter(job => job.type === type).length,
      succeeded: jobs.filter((job, index) => job.type === type && done[index].ok).length,
    })),
    notes: ['数据为当前接口快照，财务报告期与行情时点可能不同。', '当前不做历史回测，不把今天的成分与数据用于过去的策略收益计算。'],
  };
}

async function interpret(request, env) {
  const body = await request.json().catch(() => ({}));
  const text = typeof body.text === 'string' ? body.text.trim().slice(0, 500) : '';
  const followUps = (Array.isArray(body.followUps) ? body.followUps : []).slice(0, 3).map(item => String(item).trim().slice(0, 200)).filter(Boolean);
  if (!text) return json({ error: '请输入选股意图' }, 400);
  if (!env.DEEPSEEK_API_KEY) return json({ error: 'AI 解析服务尚未配置' }, 503);
  const system = `你是选股意图理解与澄清助手，只输出 JSON 对象，不输出股票、预测、买卖建议。股票池固定上证50。允许的 metric 仅有 revenue_yoy（营业收入同比增长率%）、profit_yoy（归母净利润同比增长率%）、pe_ttm（市盈率TTM倍）、pb_mrq（市净率MRQ倍）、volatility_20d（近20交易日年化波动率%）。每个 condition 为 {"metric":"...","op":"gte|lte|gt|lt|between","value":数值,"max":数值可选,"label":"简短中文解释"}。你会收到原始意图及后续补充，后续补充可修正原始描述；需综合理解，而不是只解析最后一句。模糊的经营改善默认 revenue_yoy>0 且 profit_yoy>0；估值合理默认两条条件 pe_ttm>0 与 pe_ttm<=30，并在 assumptions 中说明这只是用户可改的工作假设；走势稳定默认 volatility_20d<=30，同样说明假设。若用户给出明确阈值，按阈值。不能由这5个字段表达的要求放入 unsupported，绝不悄悄忽略。重要信息不足、含义含糊或语义冲突时，在 clarifications 中提出最多两个简短、可回答的问题；冲突条件仍保留供用户检查。输出键：conditions 数组、assumptions 字符串数组、unsupported 字符串数组、clarifications 字符串数组。最多8条条件。`;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 22000);
  try {
    const response = await fetch('https://api.deepseek.com/chat/completions', {
      method: 'POST', signal: controller.signal,
      headers: { authorization: `Bearer ${env.DEEPSEEK_API_KEY}`, 'content-type': 'application/json' },
      body: JSON.stringify({ model: 'deepseek-chat', temperature: 0, max_tokens: 900, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: system }, { role: 'user', content: JSON.stringify({ originalIntent: text, userFollowUps: followUps }) }] }),
    });
    const result = await response.json();
    if (!response.ok) throw new Error(`模型接口返回 ${response.status}`);
    const parsed = JSON.parse(result.choices?.[0]?.message?.content || '{}');
    const conditions = (Array.isArray(parsed.conditions) ? parsed.conditions : []).slice(0, 8).filter(item => {
      return item && METRICS.has(item.metric) && ['gte', 'lte', 'gt', 'lt', 'between'].includes(item.op) && Number.isFinite(item.value) && (item.op !== 'between' || Number.isFinite(item.max));
    }).flatMap(item => item.metric === 'pe_ttm' && item.op === 'between' && item.value === 0
      ? [{ metric: 'pe_ttm', op: 'gt', value: 0, label: '市盈率为正' }, { metric: 'pe_ttm', op: 'lte', value: item.max, label: String(item.label || '').slice(0, 80) }]
      : [{ metric: item.metric, op: item.op, value: item.value, ...(item.op === 'between' ? { max: item.max } : {}), label: String(item.label || '').slice(0, 80) }]).slice(0, 8);
    return json({ conditions, assumptions: stringList(parsed.assumptions), unsupported: stringList(parsed.unsupported), clarifications: stringList(parsed.clarifications), model: result.model || 'deepseek-chat' });
  } catch (error) {
    return json({ error: `AI 解析失败：${error?.message || '未知错误'}` }, 502);
  } finally { clearTimeout(timer); }
}

function stringList(value) { return (Array.isArray(value) ? value : []).slice(0, 8).map(item => String(item).slice(0, 160)); }

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === '/') return new Response(html, { headers: { 'content-type': 'text/html; charset=utf-8' } });
    if (url.pathname === '/app.css') return new Response(css, { headers: { 'content-type': 'text/css; charset=utf-8' } });
    if (url.pathname === '/app.js') return new Response(client, { headers: { 'content-type': 'application/javascript; charset=utf-8' } });
    if (url.pathname === '/engine.js') return new Response(engine, { headers: { 'content-type': 'application/javascript; charset=utf-8' } });
    if (!url.pathname.startsWith('/api/')) return new Response('Not found', { status: 404 });
    if (Number(request.headers.get('content-length') || 0) > 8192) return json({ error: '请求内容过大' }, 413);
    try {
      if (url.pathname === '/api/session' || url.pathname === '/api/account' || url.pathname.startsWith('/api/auth/') || url.pathname.startsWith('/api/strategies')) return await accountRoute(request, env, url);
      const user = await currentUser(request, env);
      if (!user) return json({ error: '请先注册或登录账号' }, 401);
      if (url.pathname === '/api/interpret' && request.method === 'POST') {
        if (!sameOrigin(request)) return json({ error: '跨站请求被拒绝' }, 403);
        if (!await rateLimit(db(env), `ai:${user.id}`, 20, 86400000)) return json({ error: '今日 AI 解析次数已达上限，可继续手动修改条件。' }, 429);
        return interpret(request, env);
      }
      if (url.pathname === '/api/market' && request.method === 'GET') {
        const refresh = url.searchParams.get('refresh') === '1';
        if (refresh) {
          if (!await rateLimit(db(env), `refresh:${user.id}`, 2, 3600000)) return json({ error: '本小时刷新次数已达上限，请稍后重试' }, 429);
          marketCache = null;
        }
        if (!refresh && marketCache && Date.now() - marketCache.time < 15 * 60 * 1000) return json({ ...marketCache.data, cache: 'memory' });
        if (!refresh) {
          const cached = await db(env).prepare('SELECT data_json, fetched_at FROM market_cache WHERE id = 1').first();
          if (cached && Date.now() - cached.fetched_at < 15 * 60 * 1000) {
            const data = JSON.parse(cached.data_json);
            marketCache = { data, time: cached.fetched_at };
            return json({ ...data, cache: 'database' });
          }
        }
        if (!marketPromise) marketPromise = loadMarket(env).finally(() => { marketPromise = null; });
        try {
          const data = await marketPromise;
          const now = Date.now();
          marketCache = { data, time: now };
          await db(env).prepare('INSERT INTO market_cache (id, data_json, fetched_at) VALUES (1, ?, ?) ON CONFLICT(id) DO UPDATE SET data_json = excluded.data_json, fetched_at = excluded.fetched_at').bind(JSON.stringify(data), now).run();
          return json({ ...data, cache: 'fresh' });
        } catch (error) { return json({ error: `金融数据获取失败：${error?.message || '未知错误'}` }, 502); }
      }
    } catch (error) {
      console.error('MINGSHAI_API_ERROR', url.pathname, error?.name || 'Error', error?.message || 'unknown');
      return json({ error: /数据库尚未连接/.test(String(error?.message)) ? '账号数据库暂不可用' : '服务暂不可用，请稍后重试' }, 503);
    }
    return new Response('Not found', { status: 404 });
  },
};
